using System.Text.Json;
using EscalaLivre.Application.Contracts;
using EscalaLivre.Application.Contracts.Documents;
using EscalaLivre.Application.Planning;
using EscalaLivre.Application.Validation;
using EscalaLivre.Domain.Scheduling;
namespace EscalaLivre.Analysis.Tests;
public sealed class EmploymentTests {
 public static IEnumerable<object[]> Cases(){using var j=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"employment-scenarios.json")));return j.RootElement.GetProperty("scenarios").EnumerateArray().Select(s=>new object[]{s.GetRawText()}).ToArray();}
 [Theory,MemberData(nameof(Cases))]public void SharedEmploymentBoundaries(string source){using var j=JsonDocument.Parse(source);var s=j.RootElement;var r=s.GetProperty("request").Deserialize<ScheduleRequest>(ScheduleJson.CreateOptions())!;var e=r.Document.Employees[0];var a=r.Document.Assignments[0];Assert.Equal(s.GetProperty("expectedRole").GetString(),EmploymentPolicy.On(e,a.Start).Role);Assert.Equal(s.GetProperty("expectedActive").GetBoolean(),EmploymentPolicy.ActiveOn(e,a.Start));var result=PureComposition.Analyze().Execute(r);Assert.Equal(!s.GetProperty("expectedActive").GetBoolean(),result.Conflicts.Any(c=>c.Code=="inactiveEmployee"));Assert.Equal(s.GetProperty("expectedMismatch").GetBoolean(),result.Conflicts.Any(c=>c.Code=="invalidShift"));var mapped=ScheduleDocumentMapper.ToProjection(ScheduleDocumentMapper.ToDto(r.Document));Assert.Equal(e.RoleHistory![0].StartsOn,mapped.Employees[0].RoleHistory![0].StartsOn);Assert.Equal(e.InactiveFrom,mapped.Employees[0].InactiveFrom);Assert.Null(DocumentSafety.Error(mapped));}
 [Fact]public void HistoryListsAreFrozenAndRegistrationEditKeepsShifts(){var source=(string)Cases().First()[0];using var j=JsonDocument.Parse(source);var r=j.RootElement.GetProperty("request").Deserialize<ScheduleRequest>(ScheduleJson.CreateOptions())!;var ids=new List<Guid>{Guid.NewGuid()};var history=new List<RoleTenure>{r.Document.Employees[0].RoleHistory![0] with{CoverageRoleIds=ids}};r=r with{Document=r.Document with{Employees=[r.Document.Employees[0] with{RoleHistory=history}]}};var mapping=PlanningDocumentMapping.Open(r);var mapped=ScheduleDocumentMapper.ToProjection(ScheduleDocumentMapper.ToDto(r.Document));history.Clear();ids.Clear();Assert.Single(mapping.ToDocument().Employees[0].RoleHistory!);Assert.Single(mapped.Employees[0].RoleHistory![0].CoverageRoleIds!);var shifts=JsonSerializer.Serialize(mapping.ToDocument().Assignments);var e=mapping.ToDocument().Employees[0];mapping.ChangeEmployee(e.Id,e with{Role="Other"});Assert.Equal(shifts,JsonSerializer.Serialize(mapping.ToDocument().Assignments));}
}
